// Decision S46-D11: a $coverage_merge that fails (a missing, corrupt or
// foreign database) and a $coverage_save that fails return SV_COV_ERROR and
// are located run-time errors: the simulation continues, no counter
// changes, and the run ends with a failure status.
//
// IEEE 1800-2009 40.3.2.4 (SystemVerilog-1800-2009.txt L66334-66336): "If
// name does not exist or does not correspond to a coverage database from
// the same design, an error shall occur. If an error occurs during loading,
// the coverage numbers generated by this simulation might not be
// meaningful." L66342-66343: "`SV_COV_ERROR. The coverage data were not
// found, or they did not correspond to this design, or another error
// occurred."
module tb;
  logic clk = 0;
  always #5 clk = ~clk;
  ap: assert property (@(posedge clk) 1'b1);
  initial begin
    $display("merge %0d", $coverage_merge(`SV_COV_ASSERTION, "s46_d11_no_such_database"));
    $display("covered %0d", $coverage_get(`SV_COV_ASSERTION, `SV_COV_HIER, $root));
    #10 $display("covered %0d", $coverage_get(`SV_COV_ASSERTION, `SV_COV_HIER, $root));
    $finish;
  end
endmodule
